def decimal_number(number: float) -> int:
    """ Given a floating point number, return the biggest power of 10 it could
    be represented with.

    For example, if number = 3.597913, it would return 1000,
    since 3.597913 could be represented as 3.59791301 * 10^3.

    >>> decimal_number(2.0)
    1
    >>> decimal_number(12.34)
    2
    >>> decimal_number(5.105)
    2
    """
    if number == 0:
        return 0
    number_as_integer = int(number)
    if number_as_integer == 0:
        return 0
    elif number_as_integer == number:
        return decimal_number(number // 10)
    else:
        return number_as_integer - number_as_integer // 10

