def split_by_parens(paren_string: str) -> List[str]:
    """ input: string representation of nested parentheses. Output is list of strings representing only outermost parentheses in each group. If multiple
    grouping are separated by a space in the string, then the output must reflect all of them.

    >>> split_by_parens('(()()) ((())) () ((())()())')
    ['(()())', '((()))', '()', '((())()())']
    """
    groups = paren_string.split(' ')
    out = []
    for i, group in enumerate(groups):
        if len(group) == 0: continue
        parens = []
        level = 0
        for c in group:
            if c == '(':
                level += 1
                parens.append(c)
            elif c == ')':
                if len(parens) > 0:
                    parens.append(c)
                else:
                    level -= 1
        out.append(''.join(parens) if level else '') 
    return out


