    contains special characters and a part that contains them.

    Return the second part.
    >>> truncate_word("I love Python!")
    'love Python!'
    """
    word_list = []
    for i, _ in enumerate(sentence):
        try:
            word_list.append(sentence[i].isalpha())
        except IndexError:
            word_list.append(False)
    words = ""

    for i, _ in enumerate(word_list):
        if word_list[i] == False:
            break
        words += sentence[i]

    return words


