def depth_of_paren_group(paren_group: str) -> int:
    """ Given a paren group (e.g. '(()())'), return the deepest level of nested parentheses.
    """
    paren_depth = 0
    deepest_depth = 0
    for c in paren_group:
        if c == '(':
            paren_depth += 1
            if deepest_depth < paren_depth:
                deepest_depth = paren_depth
        if c == ')':
            if paren_depth > 0:
                paren_depth -= 1
    return deepest_depth


