def filter_by_char(s: str, char: str) -> str:
    """ Get a substring from original string s that contains char
    >>> filter_by_char('array', 'a')
    'ar'
    >>> filter_by_char('cde', 'e')
    'cde'
    """
    if char in s:
        start = s.find(char)
        end = len(s)
        if start == -1:
            return ''
        if start == end - 1:
            end = start
        return s[start: end]

