def is_truncatable_prime(number: int) -> bool:
    """ Return True if the given number is a prime number and
    is truncatable, else return False.
    """
    if number == 2:
        return True
    elif not is_prime(number):
        return False
    else:
        for n in range(1, number // 10):
            if not is_prime(number - 10 * n):
                break
        else:
            for n in range(1, number // 10):
                if not is_prime(number + 10 * n):
                    break
            else:
                return True
    return False

def truncate_prime(lower: int, upper: int) -> int:
    """ Return the number of truncatable primes in the given range.
    """
    return sum(1 for i in range(lower, upper + 1)
                if is_truncatable_prime(i))

