def depth_set(paren_string: str, left_char: str='(', right_char: str=')') -> set:
    """ Input to this function is string of nested parentheses separated by spaces.
    Output of this function is a set representing the levels of nesting of each group.
    E.g. (()()) has maximum two levels of nesting while ((())) has three.
    """
    current_level = set([1])
    for token in paren_string.split():
        if token == left_char:
            current_level.add(current_level.union(set([len(current_level)])))
        elif token == right_char and left_char in current_level:
            current_level.remove(len(current_level))
        else:
            continue
    return current_level


